update user_account
set `total_amount`=`total_amount` - #{accountLockVo.amount}
  , `available_amount`=`available_amount` - #{accountLockVo.amount}
  , `total_pay_amount`=`total_pay_amount` + #{accountLockVo.amount}
WHERE user_id = #{accountLockVo.userId}
  AND is_deleted = 0

update user_account
set total_amount=total_amount + #{amount}
  , available_amount=available_amount + #{amount}
  , total_income_amount=total_income_amount + #{amount}
where user_id = #{userId}  and is_deleted = 0;
